INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT159-S1-Q12$batch08$, 159, 1, 12, $batch08$Most Strongly Supported$batch08$, $batch08$Many hikers now carry cell phones so they can call for emergency assistance from remote areas. Many also use their cell phones to call wildlife offices when they see poachers breaking game laws, enabling wildlife agents to reach the scene before the lawbreakers leave. Poachers, however, avoid areas they know to be frequented by hikers.$batch08$, $batch08$Which one of the following is most strongly supported by the information above?$batch08$, $batch08$D$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q12$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$Most hikers can afford cell phones.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q12$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$Poaching has decreased as cell phone use has increased.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q12$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$Wildlife agents do not usually carry cell phones.$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q12$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$Some hikers hike in areas that are not known by poachers to be frequented by hikers.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q12$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$Cell phones are becoming one of the most effective tools in the effort to protect wildlife from poachers.$batch08$, $batch08$Too Strong$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q12$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q12$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Many hikers carry cell phones. Many call wildlife offices when they see poachers breaking game laws. But poachers avoid areas they know hikers frequent.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Pause and infer. Hikers are catching poachers in the act, yet poachers stay away from known hiker areas. For both to be true, some hikers must be in places poachers don't think of as hiker territory.$batch08$), (2, $batch08$Goal$batch08$, $batch08$Some hikers hike in areas poachers don't know hikers use.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT159-S1-Q12$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$"Many" hikers carry phones. Whether most can afford one isn't addressed.$batch08$), ($batch08$B$batch08$, $batch08$No trend in poaching is given.$batch08$), ($batch08$C$batch08$, $batch08$Nothing says what agents carry.$batch08$), ($batch08$D$batch08$, $batch08$Hikers see poachers, and poachers avoid known hiker areas. So some hikers are where poachers don't expect them.$batch08$), ($batch08$E$batch08$, $batch08$"One of the most effective tools" is a ranking the passage can't support.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT159-S1-Q12$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
